DIM output_map AS MAP
output_map{"user_message"} = INPUT_DATA{"message"}{"text"}
output_map{"chat_id"} = INPUT_DATA{"message"}{"chat"}{"id"}
GLOBAL_RETURN = output_map

API_KEY$ = GETENV$("TELEGRAM_API")
chat_id = INPUT_DATA{"chat_id"}
text$ = INPUT_DATA{"ai_response"}
telegram_api_url$ = "https://api.telegram.org/bot" + API_KEY$ + "/sendMessage"
payload = { "chat_id": chat_id, "text": text$ }
HTTP.POST$(telegram_api_url$, JSON.STRINGIFY$(payload), "application/json")
GLOBAL_RETURN = INPUT_DATA
